mapper.select:
SELECT refund_order_id, payment_order_id, order_no, customer_name, paid_amount,
       refund_amount, refund_method, refund_reason, status, channel_refund_id,
       applied_at, success_at
FROM t_refund_order


        AND refund_order_id LIKE CONCAT('%', #{refundOrderId}, '%')


        AND payment_order_id LIKE CONCAT('%', #{paymentOrderId}, '%')


        AND status = #{status}


        AND refund_method = #{refundMethod}


ORDER BY applied_at DESC
LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}

SELECT COUNT(1)
FROM t_refund_order


        AND refund_order_id LIKE CONCAT('%', #{refundOrderId}, '%')


        AND payment_order_id LIKE CONCAT('%', #{paymentOrderId}, '%')


        AND status = #{status}


        AND refund_method = #{refundMethod}

SELECT id, payment_order_id, order_no, customer_name, paid_amount, channel_code, paid_at
FROM t_refund_payment_source
WHERE payment_order_id = #{paymentOrderId}

SELECT event_id, event_type, aggregate_id, payload_json, status, retry_count, last_error_message, last_relay_at, created_at, updated_at FROM t_refund_outbox_event
AND event_id LIKE CONCAT('%', #{eventId}, '%')
AND aggregate_id LIKE CONCAT('%', #{aggregateId}, '%')
AND status = #{status}
ORDER BY created_at DESC, id DESC LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}
